INSERT INTO `site_settings` (`setting_key`, `setting_value`, `updated_at`) VALUES
('aboutUs', '{\"introTitle\":\"Our Heritage\",\"introHeading\":\"The Art of Intimacy\",\"introText\":\"The art of intimacy is often misunderstood as purely physical closeness, yet its true essence runs far deeper, intertwining the emotional, intellectual, and spiritual dimensions of human connection. At its core, intimacy is the profound courage to be truly seen—to strip away the curated masks we present to the world and reveal our authentic selves, complete with our flaws, fears, and vulnerabilities. It is a delicate dance of trust, requiring the creation of a safe sanctuary where two individuals can expose their softest parts without the fear of judgment. This level of emotional transparency does not happen overnight; it is carefully cultivated through patience, empathy, and an unwavering commitment to understanding another person’s inner world.\",\"storyImage\":\"https://res.cloudinary.com/dhlvm5n1q/image/upload/f_auto,q_auto/v1781528182/testimonials/wmyzid4q6grylydf74fe.jpg\",\"carouselImages\":[\"https://res.cloudinary.com/dhlvm5n1q/image/upload/f_auto,q_auto/v1781528211/testimonials/dyrjdlzu33hn1u1vnnky.jpg\",\"https://res.cloudinary.com/dhlvm5n1q/image/upload/f_auto,q_auto/v1781528219/testimonials/lec00pqefippugmmhjas.jpg\",\"https://res.cloudinary.com/dhlvm5n1q/image/upload/f_auto,q_auto/v1781528225/testimonials/tfbdus4zlzryhtftfjju.jpg\",\"https://res.cloudinary.com/dhlvm5n1q/image/upload/f_auto,q_auto/v1781529766/testimonials/kd7hsjm59bzjx0ppoe18.jpg\",\"https://res.cloudinary.com/dhlvm5n1q/image/upload/f_auto,q_auto/v1781529780/testimonials/zk38ku9ed2i26t9u0e4v.jpg\",\"https://res.cloudinary.com/dhlvm5n1q/image/upload/f_auto,q_auto/v1781529791/testimonials/bvv3a5yxgebostgv2ox3.jpg\"],\"philosophyTitle\":\"Our Philosophy\",\"philosophyHeading\":\"Beauty in Every Thread\",\"philosophyText\":\"The art of intimacy is often misunderstood as purely physical closeness, yet its true essence runs far deeper, intertwining the emotional, intellectual, and spiritual dimensions of human connection. At its core, intimacy is the profound courage to be truly seen—to strip away the curated masks we present to the world and reveal our authentic selves, complete with our flaws, fears, and vulnerabilities. It is a delicate dance of trust, requiring the creation of a safe sanctuary where two individuals can expose their softest parts without the fear of judgment. This level of emotional transparency does not happen overnight; it is carefully cultivated through patience, empathy, and an unwavering commitment to understanding another person’s inner world.\",\"philosophyImages\":[\"https://res.cloudinary.com/dhlvm5n1q/image/upload/f_auto,q_auto/v1781528243/testimonials/bsmigjeqe2g6xunvrfwl.jpg\",\"https://res.cloudinary.com/dhlvm5n1q/image/upload/f_auto,q_auto/v1781528252/testimonials/ptcekxpxyec8lckavg5w.jpg\",\"https://res.cloudinary.com/dhlvm5n1q/image/upload/f_auto,q_auto/v1781529046/testimonials/a0i5ezxq9tld2ju6hfhh.jpg\",\"https://res.cloudinary.com/dhlvm5n1q/image/upload/f_auto,q_auto/v1781529258/testimonials/ukdzmigrmwd7ocewdvr7.jpg\"]}', '2026-06-15 13:23:15'),
('aboutUsData', '{\"heroQuote\":\"\\\"Inspiring dressing up & undressing\\\"\",\"heroParagraphs\":[\"We are a luxury lingerie, ready-to-wear, and swim brand. Our name speaks to the unique duality of our spirit.\",\"We take a fashion approach to lingerie, and apply a lingerie language to fashion. Our products are delicate and sophisticated, using luxury fabrics and bespoke embroideries crafted by world-class artisans.\",\"We are constantly thinking about the emotion attached to lingerie, and our goal is to create products that make women of all ages and sizes feel their best.\"],\"heroImage\":\"https:\\/\\/res.cloudinary.com\\/dhlvm5n1q\\/image\\/upload\\/v1781874549\\/about_us\\/tfbrcdqroqri60dyqzfj.jpg\",\"fataleHashtag\":\"#underpure\",\"fataleImages\":[{\"id\":1,\"src\":\"\\/images\\/FDM_051926_77426full.jpg\",\"hasPlay\":false},{\"id\":2,\"src\":\"\\/images\\/FDM_071025_29928_full.jpg\",\"hasPlay\":false},{\"id\":3,\"src\":\"\\/images\\/FDM_050125_66612full.jpg\",\"hasPlay\":false}],\"designPhilosophyLabel\":\"DESIGN PHILOSOPHY\",\"designPhilosophyParagraphs\":[\"Our ready-to-wear and swim collections embody this same spirit. Lingerie-inspired pieces are tastefully provocative, while maintaining bold style and practical wearability.\",\"Our customer is comfortable embracing both her femininity and her confidence, knowing that these two qualities make her unstoppable.\"],\"philosophyImages\":[{\"id\":1,\"src\":\"\\/images\\/look_11-36__campaign.jpg\"},{\"id\":2,\"src\":\"\\/images\\/FDM_100925_5542full.jpg\"},{\"id\":3,\"src\":\"\\/images\\/FDM_112125_34850full_5662602b-220d-4138-aac2-0610ae56b6fa.jpg\"},{\"id\":4,\"src\":\"\\/images\\/FDM_051926_77495full_1.jpg\"}]}', '2026-06-19 13:09:22'),
