('cartSettings', '{\"basic\":{\"title\":\"Your bag\",\"emptyMessage\":\"Your bag is empty.\",\"checkoutText\":\"CONTINUE TO CHECKOUT\",\"viewBagText\":\"VIEW BAG\",\"subtotalText\":\"Subtotal\",\"removeText\":\"Remove\",\"taxShippingText\":\"Taxes and shipping calculated at checkout\"},\"shippingBar\":{\"enabled\":true,\"threshold\":2500,\"awayMessage\":\"You\'re $X away from free shipping!\",\"achievedMessage\":\"You\'ve unlocked free shipping!\",\"progressColor\":\"#000000\",\"backgroundColor\":\"#e5e7eb\"},\"gifting\":{\"enabled\":true,\"title\":\"Gifting a lover?\",\"description\":\"Make it extra special with a Fleur gift box.\",\"image\":\"\",\"options\":\"HEART-$28, STANDARD-$15\",\"products\":[{\"id\":1781804397123,\"name\":\"Ultra Flex Support Bra\",\"price\":\"1500.00\"}]},\"discover\":{\"enabled\":true,\"title\":\"Discover new in lingerie, clothing and other exclusive styles.\",\"collections\":[{\"id\":1781804406280,\"name\":\"Butterfly Bra\",\"image\":\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778761744\\/otsaqnedwxkdk2cbfqbh.jpg\",\"url\":\"\\/collections\\/butterfly-bra\"},{\"id\":1781804411732,\"name\":\"Sporty Chic Sets\",\"image\":\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778933131\\/bmdxukeyjge0lypflj3v.jpg\",\"url\":\"\\/collections\\/sporty-chic-sets\"},{\"id\":1781804414223,\"name\":\"Camisole\",\"image\":\"https:\\/\\/res.cloudinary.com\\/dcdogxx8v\\/image\\/upload\\/v1778942240\\/xdiqonukxdwlnoahkkol.jpg\",\"url\":\"\\/collections\\/camisole\"}]},\"giftNote\":{\"enabled\":true,\"text\":\"+ Add a free gift note\"},\"crossSells\":{\"enabled\":true,\"title\":\"Pairs Well With\"},\"loyaltyBanner\":{\"enabled\":true,\"title\":\"Underpure with Benefits\",\"description\":\"Join our loyalty program to access exclusive benefits and earn Fleur Coins every time you shop.\",\"buttonText\":\"SIGN UP\",\"footerText\":\"Already a member? Log in\"},\"policies\":{\"enabled\":true,\"title\":\"Our Policies\"}}', '202